// Each candidate is generated by the user's trained ZeroAI model, not an API.
import {ByteLevelBPE} from './tokenizer.js';
import {ZeroAIModel,sample} from './model.js';
import {rank,logProbability,paraphraseNumericQuestion} from './quality_v17.js';
let model=null,tok=null;
function report(type,fields={}){self.postMessage({type,...fields});}
self.onmessage=async event=>{
  const d=event.data;
  try{
    if(d.type==='load'){
      model=new ZeroAIModel(d.manifest,d.weights);tok=new ByteLevelBPE(d.tokenizer);
      for(const [token,id] of Object.entries(d.manifest.special_token_ids))
        if(tok.special[token]!==id)throw Error('Tokenizer special ID mismatch: '+token);
      report('ready',{step:d.manifest.checkpoint_step,vocab:model.cfg.vocab_size,context:model.cfg.block_size});
    }else if(d.type==='generate'){
      if(!model||!tok)throw Error('Model not loaded');
      const question=String(d.question||'').trim();
      if(!question)throw Error('質問を入力してね');
      const codeMode=!!d.codeMode;
      const nCandidates=Math.max(1,Math.min(4,Math.trunc(Number(d.candidates)||1)));
      const alt=codeMode?paraphraseNumericQuestion(question):null;
      const questions=alt?[question,alt]:[question];
      const starts=questions.map(q=>{
        const ids=tok.encode(`<user>\n${q}\n<bot>\n`);
        if(ids.length>=model.cfg.block_size-1)throw Error('入力が長すぎます。512トークン以下にしてください');
        const session=model.session();return {session,logits:session.prefill(ids),length:ids.length};
      });
      const maxNew=Math.min(Math.max(1,Math.trunc(Number(d.maxTokens)||64)),model.cfg.block_size-Math.max(...starts.map(x=>x.length)));
      const stopIds=new Set([tok.special['<end>'],tok.special['<user>'],tok.special['<bot>'],tok.special['<eof>']]);
      const candidates=[];
      for(let c=0;c<nCandidates;c++){
        const useAlt=!!alt&&(c%2===1);
        const start=starts[useAlt?1:0];
        const session=start.session.clone();let logits=start.logits;
        let result=[],sumLP=0,stopped=false;
        const deterministic=(c===0||(useAlt&&c===1));
        const temp=(deterministic?0.45:(Number(d.temperature)||0.62));
        const topK=(deterministic?1:Math.max(2,Number(d.topK)||25));
        const topP=(deterministic?1:(Number(d.topP)||0.95));
        report('notice',{text:`端末内で候補 ${c+1}/${nCandidates} を生成中…${useAlt?'（質問を言い換え）':''}`});
        for(let t=0;t<maxNew&&session.pos<model.cfg.block_size;t++){
          const next=sample(logits,temp,topK,topP);
          if(stopIds.has(next)){stopped=true;break;}
          result.push(next);sumLP+=logProbability(logits,next);
          if(c===0&&(t%3===0||t===maxNew-1))report('progress',{output:tok.decode(result),tokens:result.length});
          logits=session.step(next);
          if(t%4===3)await new Promise(resolve=>setTimeout(resolve,0));
        }
        candidates.push({text:tok.decode(result),tokens:result.length,avgLogprob:result.length?sumLP/result.length:-100,stopped,source:useAlt?'言い換え':'原文'});
      }
      const result=rank(question,candidates,codeMode);
      const picked=candidates[result.index];
      report('done',{output:picked.text,tokens:picked.tokens,
        bestIndex:result.index,candidates:candidates.map((c,i)=>({text:c.text,tokens:c.tokens,
        avgLogprob:c.avgLogprob,score:result.reports[i].score,reason:result.reports[i].reason,
        selected:i===result.index,source:c.source})),verification:result.reports[result.index].verification,question,codeMode});
    }
  }catch(e){report('error',{error:String(e?.message||e)});}
};
